BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS apscheduler_jobs (
	id VARCHAR(191) NOT NULL, 
	next_run_time FLOAT, 
	job_state BLOB NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS availability_block (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    date DATE NOT NULL,
    start_time TIME NOT NULL,
    end_time TIME NOT NULL,
    total_minutes INTEGER NOT NULL,
    booked_minutes INTEGER NOT NULL DEFAULT 0,
    status VARCHAR(20) NOT NULL DEFAULT 'available',
    is_active BOOLEAN NOT NULL DEFAULT 1,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES user(id)
);
CREATE TABLE IF NOT EXISTS booking (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    client_user_id INTEGER NOT NULL,
    consultant_user_id INTEGER NOT NULL,
    availability_block_id INTEGER,
    booking_date DATE NOT NULL,
    start_time VARCHAR(5) NOT NULL,
    end_time VARCHAR(5) NOT NULL,
    duration_minutes INTEGER NOT NULL,
    status VARCHAR(20) DEFAULT 'pending',
    price DECIMAL(10, 2),
    payment_status VARCHAR(20) DEFAULT 'pending',
    payment_method VARCHAR(50),
    transaction_id VARCHAR(100),
    meeting_link VARCHAR(500),
    client_notes TEXT,
    consultant_notes TEXT,
    cancellation_reason TEXT,
    cancelled_by INTEGER,
    cancelled_at DATETIME,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, client_joined_at DATETIME DEFAULT NULL, consultant_joined_at DATETIME DEFAULT NULL, recording_sid VARCHAR(255) DEFAULT NULL, recording_resource_id VARCHAR(255) DEFAULT NULL, recording_status VARCHAR(50) DEFAULT 'not_started', recording_url TEXT DEFAULT NULL, recording_duration INTEGER DEFAULT NULL, recording_file_size INTEGER DEFAULT NULL, recording_started_at DATETIME DEFAULT NULL, recording_completed_at DATETIME DEFAULT NULL, stripe_checkout_session_id TEXT, stripe_payment_intent_id TEXT, call_started_at DATETIME DEFAULT NULL,
    FOREIGN KEY (client_user_id) REFERENCES user(id) ON DELETE CASCADE,
    FOREIGN KEY (consultant_user_id) REFERENCES user(id) ON DELETE CASCADE,
    FOREIGN KEY (availability_block_id) REFERENCES availability_block(id) ON DELETE SET NULL,
    FOREIGN KEY (cancelled_by) REFERENCES user(id) ON DELETE SET NULL,
    CHECK (status IN ('pending', 'confirmed', 'completed', 'cancelled', 'no_show')),
    CHECK (payment_status IN ('pending', 'paid', 'refunded', 'failed')),
    CHECK (duration_minutes IN (30, 60, 90, 120))
);
CREATE TABLE IF NOT EXISTS category (
    id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    name VARCHAR NOT NULL UNIQUE,
    slug VARCHAR NOT NULL UNIQUE,
    icon VARCHAR DEFAULT '🎯',
    description VARCHAR,
    target VARCHAR,
    color VARCHAR DEFAULT '#4CAF50'
);
CREATE TABLE IF NOT EXISTS community_answers (
	id INTEGER NOT NULL, 
	question_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	content VARCHAR NOT NULL, 
	upvotes INTEGER NOT NULL, 
	is_accepted BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(question_id) REFERENCES community_questions (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE IF NOT EXISTS community_contacts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    question_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    
    -- Foreign keys
    FOREIGN KEY (question_id) REFERENCES community_questions(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES user(id) ON DELETE CASCADE,
    
    -- Constraint univoco: un utente può incrementare il contatore una sola volta per domanda
    UNIQUE(question_id, user_id)
);
CREATE TABLE IF NOT EXISTS community_likes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    question_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    
    -- Foreign keys
    FOREIGN KEY (question_id) REFERENCES community_questions(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES user(id) ON DELETE CASCADE,
    
    -- Constraint univoco: un utente può mettere un solo like per domanda
    UNIQUE(question_id, user_id)
);
CREATE TABLE IF NOT EXISTS community_questions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    category_id INTEGER,
    title VARCHAR(200) NOT NULL,
    description VARCHAR(5000) NOT NULL,
    status VARCHAR(50) DEFAULT 'open' NOT NULL,
    views INTEGER DEFAULT 0 NOT NULL,
    upvotes INTEGER DEFAULT 0 NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    FOREIGN KEY (user_id) REFERENCES user(id) ON DELETE CASCADE,
    FOREIGN KEY (category_id) REFERENCES category(id) ON DELETE SET NULL
);
CREATE TABLE IF NOT EXISTS configuration_property (
    id INT AUTO_INCREMENT PRIMARY KEY,
    property_key VARCHAR(100) NOT NULL UNIQUE,
    property_value VARCHAR(500) NOT NULL,
    description TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, updated_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS consultation (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	consultant_id INTEGER NOT NULL, 
	status VARCHAR NOT NULL, 
	scheduled_at DATETIME, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES user (id), 
	FOREIGN KEY(consultant_id) REFERENCES user (id)
);
CREATE TABLE IF NOT EXISTS consultation_offers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    consultant_user_id INTEGER NOT NULL,
    client_user_id INTEGER NOT NULL,
    price REAL NOT NULL CHECK(price > 0),
    duration_minutes INTEGER NOT NULL CHECK(duration_minutes > 0),
    status VARCHAR(20) DEFAULT 'pending',
    booking_id INTEGER,
    message TEXT,
    expires_at TIMESTAMP NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (consultant_user_id) REFERENCES user(id),
    FOREIGN KEY (client_user_id) REFERENCES user(id),
    FOREIGN KEY (booking_id) REFERENCES booking(id)
);
CREATE TABLE IF NOT EXISTS conversations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user1_id INTEGER NOT NULL,
    user2_id INTEGER NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    
    FOREIGN KEY (user1_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (user2_id) REFERENCES users(id) ON DELETE CASCADE,
    
    -- ✅ Constraint: ogni coppia di utenti ha UNA sola conversazione
    UNIQUE(user1_id, user2_id),
    
    -- ✅ Check: user1_id sempre < user2_id (normalizzazione)
    CHECK (user1_id < user2_id)
);
CREATE TABLE IF NOT EXISTS example (
	id INTEGER NOT NULL, 
	name VARCHAR NOT NULL, 
	description VARCHAR NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS "imagelink" (
	"id"	INTEGER NOT NULL,
	"url"	VARCHAR NOT NULL,
	"name"	VARCHAR NOT NULL,
	"description"	VARCHAR NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS message_counter_reset (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    conversation_id INTEGER NOT NULL,
    user1_id INTEGER NOT NULL,
    user2_id INTEGER NOT NULL,
    booking_id INTEGER,
    reset_reason TEXT DEFAULT 'payment_booking',
    reset_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (conversation_id) REFERENCES conversation(id) ON DELETE CASCADE,
    FOREIGN KEY (user1_id) REFERENCES user(id) ON DELETE CASCADE,
    FOREIGN KEY (user2_id) REFERENCES user(id) ON DELETE CASCADE,
    FOREIGN KEY (booking_id) REFERENCES booking(id) ON DELETE SET NULL,
    UNIQUE(conversation_id, booking_id)
);
CREATE TABLE IF NOT EXISTS messages (
	id INTEGER NOT NULL, 
	conversation_id INTEGER NOT NULL, 
	sender_id INTEGER NOT NULL, 
	content VARCHAR NOT NULL, 
	created_at DATETIME NOT NULL, 
	is_read BOOLEAN NOT NULL, 
	is_system_message BOOLEAN NOT NULL, 
	consultation_offer_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(conversation_id) REFERENCES conversations (id), 
	FOREIGN KEY(sender_id) REFERENCES user (id), 
	FOREIGN KEY(consultation_offer_id) REFERENCES consultation_offers (id)
);
CREATE TABLE IF NOT EXISTS notification_types (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type_key VARCHAR(50) UNIQUE NOT NULL,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    
    -- Flags configurazione
    in_app BOOLEAN DEFAULT 1 NOT NULL,
    send_email BOOLEAN DEFAULT 0 NOT NULL,
    
    -- Configurazione email
    email_subject VARCHAR(200),
    email_template VARCHAR(100),
    
    -- Metadata
    is_active BOOLEAN DEFAULT 1 NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS notifications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    type VARCHAR(50) NOT NULL,
    title VARCHAR(255) NOT NULL,
    message TEXT NOT NULL,
    related_booking_id INTEGER,
    related_user_id INTEGER,
    action_url VARCHAR(500),
    is_read BOOLEAN NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES user(id) ON DELETE CASCADE,
    FOREIGN KEY (related_booking_id) REFERENCES booking(id) ON DELETE SET NULL,
    FOREIGN KEY (related_user_id) REFERENCES user(id) ON DELETE SET NULL
);
CREATE TABLE IF NOT EXISTS "user" (
	"id"	INTEGER NOT NULL,
	"email"	VARCHAR NOT NULL UNIQUE,
	"password_md5"	VARCHAR NOT NULL,
	"confirmation_code"	VARCHAR(6),
	"confirmed"	INTEGER NOT NULL DEFAULT 0,
	"created_at"	VARCHAR,
	"nome"	VARCHAR,
	"cognome"	TEXT,
	"professione"	VARCHAR,
	"descrizione"	TEXT,
	"bollini"	INTEGER DEFAULT 0,
	"consulenze_acquistate"	INTEGER DEFAULT 0,
	"consulenze_vendute"	INTEGER DEFAULT 0,
	"category_id"	INTEGER,
	"aree_interesse"	VARCHAR,
	"prezzo_consulenza"	INTEGER DEFAULT 150,
	"durata_consulenza"	INTEGER DEFAULT 60,
	"profile_picture"	TEXT, is_verified INTEGER DEFAULT 0, user_type_id INTEGER DEFAULT 1, is_anonymous BOOLEAN DEFAULT 0,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS user_type (
    id INTEGER PRIMARY KEY,
    name VARCHAR(50) NOT NULL UNIQUE,
    description VARCHAR(255)
);
