INSERT INTO "user" ("id","email","password_md5","confirmation_code","confirmed","created_at","nome","cognome","professione","descrizione","bollini","consulenze_acquistate","consulenze_vendute","category_id","aree_interesse","prezzo_consulenza","durata_consulenza","profile_picture","is_verified","user_type_id","is_anonymous") VALUES (11,'laura.rossi@helpy.com','482c811da5d5b4bc6d497ffa98491e38',NULL,1,'2025-10-20 14:47:11','Laura Rossi',NULL,'Career Coach & HR Consultant','Con oltre 15 anni di esperienza nel settore HR e career coaching, aiuto professionisti a fare il salto di carriera che desiderano. Ho lavorato con centinaia di clienti per ottimizzare CV, prepararsi ai colloqui e negoziare offerte migliori. La mia specialità è trasformare la tua esperienza in una narrazione vincente.',0,0,47,1,'Cambio carriera,Colloqui di lavoro,Negoziazione stipendio,CV e LinkedIn,Leadership femminile',120,60,NULL,0,1,0),
 (12,'marco.bianchi@helpy.com','482c811da5d5b4bc6d497ffa98491e38',NULL,1,'2025-10-20 14:47:11','Marco Bianchi',NULL,'Tech Recruiter & Startup Advisor','Lavoro da 10 anni nel recruiting per aziende tech e startup. So esattamente cosa cercano i recruiter e come far risaltare il tuo profilo. Ti aiuto a posizionarti nel mercato tech, prepararti per i colloqui tecnici e negoziare package retributivi competitivi. Ho aiutato oltre 200 developer e PM a ottenere ruoli in FAANG e unicorn europee.',0,0,89,1,'Carriera nel tech,Colloqui tecnici,Passaggio a startup,Negoziazione RAL,Portfolio sviluppatore',150,60,NULL,0,1,0),
 (13,'giulia.ferrari@helpy.com','482c811da5d5b4bc6d497ffa98491e38',NULL,1,'2025-10-20 14:47:11','Giulia Ferrari',NULL,'Executive Coach & Leadership Developer','Aiuto manager e professionisti a fare il salto verso ruoli di leadership. Con un background in psicologia organizzativa e 12 anni come C-level in aziende Fortune 500, conosco le sfide della crescita professionale ai massimi livelli. Ti guido nello sviluppo delle soft skills necessarie per guidare team e influenzare stakeholder.',0,0,34,1,'Passaggio a ruoli manageriali,Leadership,Gestione conflitti,Public speaking,Crescita professionale',200,90,NULL,0,1,0),
 (14,'andrea.conti@helpy.com','482c811da5d5b4bc6d497ffa98491e38',NULL,1,'2025-10-20 14:47:11','Andrea Conti',NULL,'Freelance & Business Consultant','Ho trasformato la mia carriera da dipendente a freelance di successo 5 anni fa. Ora fattura oltre €150K/anno e aiuto altri professionisti a fare lo stesso. Ti insegno come trovare clienti, prezzare i tuoi servizi, gestire la partita IVA e costruire un business sostenibile. Perfetto per chi vuole lasciare il posto fisso e diventare indipendente.',0,0,62,3,'Diventare freelance,Trovare clienti,Pricing e contratti,Gestione fiscale,Work-life balance',100,60,NULL,0,1,0),
 (15,'sara.lombardi@helpy.com','482c811da5d5b4bc6d497ffa98491e38',NULL,1,'2025-10-20 14:47:11','Sara Lombardi',NULL,'Senior Product Manager @ Tech Unicorn','Sono Product Manager da 8 anni in aziende come Amazon e Spotify. Aiuto professionisti a fare il passaggio a Product Management, anche senza esperienza diretta. Ti guido nella preparazione del portfolio, nella comprensione del product thinking e nella preparazione ai case interview. Ho mentorizzato 50+ persone verso ruoli PM.',0,0,51,2,'Diventare Product Manager,Case interview,Product portfolio,Metriche di prodotto,Roadmap strategy',180,75,NULL,0,1,0),
 (16,'luca.marino@helpy.com','482c811da5d5b4bc6d497ffa98491e38',NULL,1,'2025-10-20 14:47:11','Luca Marino',NULL,'Remote Work Expert & Digital Nomad','Lavoro in remoto da 6 anni viaggiando in 40+ paesi. Ti aiuto a trovare e negoziare posizioni remote, ottimizzare la produttività da casa, e costruire una carriera location-independent. Conosco tutti i migliori job board remote, come distinguersi nelle candidature e come gestire timezone e comunicazione asincrona.',0,0,73,8,'Trovare lavoro remote,Produttività da remoto,Vita da nomade digitale,Gestione timezone,Work-life balance',90,45,NULL,0,1,0),
 (17,'elena.russo@helpy.com','482c811da5d5b4bc6d497ffa98491e38',NULL,1,'2025-10-20 14:47:11','Elena Russo',NULL,'Career Transition Coach','Mi occupo di aiutare professionisti a cambiare completamente settore o ruolo. Ho guidato oltre 100 persone in transizioni di carriera radicali: da ingegnere a UX designer, da avvocato a product manager, da insegnante a data analyst. Ti aiuto a identificare competenze trasferibili, riqualificarti velocemente e posizionarti nel nuovo campo.',0,0,28,1,'Cambio settore,Riqualificazione professionale,Competenze trasferibili,Transizione di carriera,Pivoting',130,60,NULL,0,1,0),
 (18,'francesco.greco@helpy.com','482c811da5d5b4bc6d497ffa98491e38',NULL,1,'2025-10-20 14:47:11','Francesco Greco',NULL,'LinkedIn Strategist & Personal Branding Coach','Ho costruito una community di 50K follower su LinkedIn e aiuto professionisti a fare lo stesso. Ti insegno come ottimizzare il profilo LinkedIn, creare contenuti virali, fare networking strategico e trasformare la tua presenza online in opportunità concrete. Ho aiutato 150+ clienti a 10X la visibilità e ricevere offerte di lavoro spontanee.',0,0,95,4,'Ottimizzazione LinkedIn,Content creation,Personal branding,Networking digitale,Employer branding',110,60,'/uploads/profile_pictures/18_7ac90e85.jpg',0,1,0),
